fromfastapi import APIRouter, HTTPException, status
from pydantic import BaseModel
from typing import List, Optional

router = APIRouter(prefix="/products", tags=["products"])


class ProductBase(BaseModel):
    name: str
    description: Optional[str] = None
    price: float
    sku: str
    category: Optional[str] = None
    in_stock: bool = True


class ProductCreate(ProductBase):
    pass


class ProductUpdate(BaseModel):
    name: Optional[str] = None
    description: Optional[str] = None
    price: Optional[float] = None
    sku: Optional[str] = None
    category: Optional[str] = None
    in_stock: Optional[bool] = None


class ProductOut(ProductBase):
    id: int

    class Config:
        from_attributes = True


# In-memory store for legacy/inline usage
_products: dict[int, dict] = {}
_next_id = 1


def _get_or_404(product_id: int) -> dict:
    product = _products.get(product_id)
    if product is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Product {product_id} not found",
        )
    return product


@router.get("/", response_model=List[ProductOut])
def list_products():
    return list(_products.values())


@router.get("/{product_id}", response_model=ProductOut)
def get_product(product_id: int):
    product = _get_or_404(product_id)
    return product


@router.post("/", response_model=ProductOut, status_code=status.HTTP_201_CREATED)
def create_product(payload: ProductCreate):
    global _next_id
    product = payload.model_dump()
    product["id"] = _next_id
    _products[_next_id] = product
    _next_id += 1
    return product


@router.put("/{product_id}", response_model=ProductOut)
def replace_product(product_id: int, payload: ProductCreate):
    existing = _get_or_404(product_id)
    updated = payload.model_dump()
    updated["id"] = product_id
    _products[product_id] = updated
    return updated


@router.patch("/{product_id}", response_model=ProductOut)
def update_product(product_id: int, payload: ProductUpdate):
    existing = _get_or_404(product_id)
    updates = payload.model_dump(exclude_unset=True)
    existing.update(updates)
    return existing


@router.delete("/{product_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_product(product_id: int):
    _get_or_404(product_id)
    del _products[product_id]
    return None

"""
Aurem LLM Proxy Router

Provides proxy endpoints that forward requests to upstream LLM providers
with optional authentication, rate limiting, and response logging.
"""

from __future__ import annotations

import os
from typing import Any, Dict, Optional

import httpx
from fastapi import APIRouter, Depends, HTTPException, Request, Response
from fastapi.responses import StreamingResponse
from pydantic import BaseModel, Field

router = APIRouter(prefix="/llm", tags=["llm-proxy"])

DEFAULT_TIMEOUT = float(os.getenv("LLM_PROXY_TIMEOUT", "120"))
UPSTREAM_BASE_URL = os.getenv("LLM_PROXY_UPSTREAM_URL", "")


class ProxyRequest(BaseModel):
    """Model representing a proxied LLM request body."""

    model: str = Field(..., description="The model identifier to target.")
    messages: list[Dict[str, Any]] = Field(
        ..., description="Conversation messages to send."
    )
    temperature: Optional[float] = Field(
        default=None, ge=0.0, le=2.0, description="Sampling temperature."
    )
    max_tokens: Optional[int] = Field(
        default=None, gt=0, description="Maximum tokens to generate."
    )
    stream: Optional[bool] = Field(
        default=False, description="Whether to stream the response."
    )
    extra: Optional[Dict[str, Any]] = Field(
        default_factory=dict,
        description="Additional provider-specific parameters to forward.",
    )


def _build_upstream_payload(body: ProxyRequest) -> Dict[str, Any]:
    """Construct the payload dictionary sent to the upstream provider."""
    payload: Dict[str, Any] = {
        "model": body.model,
        "messages": body.messages,
    }
    if body.temperature is not None:
        payload["temperature"] = body.temperature
    if body.max_tokens is not None:
        payload["max_tokens"] = body.max_tokens
    if body.stream is not None:
        payload["stream"] = body.stream
    if body.extra:
        payload.update(body.extra)
    return payload


def _get_api_key() -> str:
    """Retrieve the upstream API key from environment variables."""
    api_key = os.getenv("LLM_PROXY_API_KEY", "")
    if not api_key:
        raise HTTPException(
            status_code=500,
            detail="LLM_PROXY_API_KEY is not configured on the server.",
        )
    return api_key


def _get_upstream_url(path: str) -> str:
    """Build the full upstream URL for a given path."""
    if not UPSTREAM_BASE_URL:
        raise HTTPException(
            status_code=500,
            detail="LLM_PROXY_UPSTREAM_URL is not configured on the server.",
        )
    return f"{UPSTREAM_BASE_URL.rstrip('/')}/{path.lstrip('/')}"


async def _forward_request(
    method: str,
    path: str,
    body: ProxyRequest,
    *,
    stream: bool = False,
) -> Response | StreamingResponse:
    """Forward a request to the upstream LLM provider."""
    api_key = _get_api_key()
    url = _get_upstream_url(path)
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    payload = _build_upstream_payload(body)

    if stream or body.stream:
        return StreamingResponse(
            _stream_upstream(method, url, headers, payload),
            media_type="text/event-stream",
        )

    async with httpx.AsyncClient(timeout=DEFAULT_TIMEOUT) as client:
        try:
            response = await client.request(
                method, url, headers=headers, json=payload
            )
        except httpx.RequestError as exc:
            raise HTTPException(
                status_code=502, detail=f"Upstream request failed: {exc}"
            ) from exc

    if response.status_code >= 400:
        raise HTTPException(
            status_code=response.status_code,
            detail=response.text,
        )

    return Response(content=response.content, media_type="application/json")


async def _stream_upstream(
    method: str,
    url: str,
    headers: Dict[str, str],
    payload: Dict[str, Any],
):
    """Yield chunks from a streaming upstream response."""
    async with httpx.AsyncClient(timeout=DEFAULT_TIMEOUT) as client:
        async with client.stream(
            method, url, headers=headers, json=payload
        ) as response:
            if response.status_code >= 400:
                body = await response.aread()
                raise HTTPException(
                    status_code=response.status_code,
                    detail=body.decode(errors="replace"),
                )
            async for chunk in response.aiter_bytes():
                yield chunk


@router.post("/chat/completions")
async def chat_completions(body: ProxyRequest) -> Response | StreamingResponse:
    """Proxy a chat completion request to the upstream provider."""
    return await _forward_request("POST", "/chat/completions", body)


@router.post("/completions")
async def completions(body: ProxyRequest) -> Response | StreamingResponse:
    """Proxy a legacy text completion request to the upstream provider."""
    return await _forward_request("POST", "/completions", body)


@router.get("/health")
async def health() -> Dict[str, str]:
    """Simple health-check endpoint for the proxy router."""
    return {"status": "ok"}

